const assert = require('node:assert/strict')
const { once } = require('node:events')
const { Vec3 } = require('vec3')
const { until, pause, connect, inventory, command, clickModeJoin, basketShot, shortShot, release } = require('./parkland-41.cjs')

// Three short holes generated by the Ace Race layout with course seed 41.
const fixture = [
  [new Vec3(72.5,66,88.5),new Vec3(88.5,66.9,72.5)],
  [new Vec3(152.5,66,56.5),new Vec3(200.5,66.9,56.5)],
  [new Vec3(280.5,66,56.5),new Vec3(312.5,66.9,72.5)]
]
const opening = 'Ace Race: One throw per hole. Most aces wins, and equal totals share a place.'
const restored = state => state.messages.includes('Round complete!')
const countAces = aces => aces+(aces===1 ? ' ace' : ' aces')

function active(players) {
  return players.find(state=>state.name===players[0].turns.at(-1))
}

async function start(players, party) {
  await until(()=>players.every(state=>state.spawned),'clients join the lobby')
  const [first, ...others] = players
  if (party) {
    for (const member of others) {
      await command(first,'party invite '+member.name,/Party invite sent/)
      await command(member,'party accept',/joined the party/)
    }
    const opened = once(first.bot,'windowOpen')
    await command(first,'menu')
    const [menu] = await opened
    await until(()=>menu.slots[23]?.name==='target','Ace Race is in the round picker')
    await clickModeJoin(first, 23)
    await until(()=>first.messages.includes('Your party has been queued for Ace Race.'),'the party joins the Ace Race queue')
  } else {
    await Promise.all(players.map(state=>command(state,'queue ace-race',/You have been queued for Ace Race/)))
  }
  await until(()=>players.every(state=>state.messages.includes(opening)),'the round starts',120000)
  for (const state of players) await command(state,'shot timing on',/timing on/)
}

async function rejectThrow(state, expected) {
  const before = state.messages.length
  state.bot.chat('/throwdisc driver')
  await until(()=>state.messages.slice(before).includes(expected),'the extra or out-of-turn throw is rejected')
  assert.ok(!state.messages.slice(before).some(line=>line.startsWith('Throw meter started')))
}

async function playHole(players, hole, outcomes) {
  const observer = players[0]
  const [tee,basket] = fixture[hole-1]
  await until(()=>players.every(state=>state.bot.game.gameMode==='adventure')
    && active(players)?.bot.entity.position.distanceTo(tee)<2,'all players return from the hole '+hole+' flyover')
  await command(observer,'status',new RegExp('^Hole: '+hole+'/3$'))
  await pause(300)
  if (hole===1) {
    const waiting = players.find(state=>state!==active(players))
    await rejectThrow(waiting,"It is not your team's turn.")
  }
  const used = new Set()
  for (let i=0; i<players.length; i++) {
    await until(()=>{
      const state = active(players)
      return state && !used.has(state)
    },'a new player takes a turn on hole '+hole+'; observed turns '+observer.turns.join(', '))
    const state = active(players)
    used.add(state)
    const outcome = outcomes[players.indexOf(state)]
    const before = observer.messages.length
    const turns = observer.turns.length
    if (outcome==='pass') {
      await command(state,'concede',/missed hole .*\(Hole conceded\)\./)
    } else if (outcome!=='timeout') {
      await command(state,'lie')
      await pause(200)
      assert.ok(state.bot.entity.position.distanceTo(tee)<2,'the throw starts at the tee')
      const shot = outcome==='ace' ? await basketShot(state.bot,'driver',basket) : shortShot(state.bot,20,-.6,basket)
      assert.ok(shot,'the fixture has a clear scoring line on hole '+hole)
      await release(state,shot)
      if (outcome==='ace') state.aces++
    }
    const result = outcome==='ace' ? state.name+' aced hole '+hole+'! ('+countAces(state.aces)+')'
      : state.name+' missed hole '+hole+(outcome==='pass' ? ' (Hole conceded).' : outcome==='timeout' ? ' (Turn timed out).' : '.')
    const turnSeconds = Number(process.env.NDG_TEST_TURN_SECONDS || 35)
    const deadline = outcome==='timeout' ? (turnSeconds+15)*1000 : 50000
    await until(()=>observer.messages.slice(before).includes(result),result,deadline)
    await until(()=>observer.turns.length>turns || restored(observer),'the next turn or final result is reached')
    if (i<players.length-1) {
      await rejectThrow(state,'Your Ace Race attempt is complete. Wait for the next hole.')
      const status = outcome==='ace' ? 'Ace' : 'Miss'
      await command(state,'status',new RegExp('^Aces: '+state.aces+' • This hole: '+status+'$'))
    }
  }
  console.log('PASS: hole '+hole+' ('+Math.round(tee.distanceTo(basket))+' blocks), '+outcomes.join(', '))
}

async function finish(players, result, standings) {
  await until(()=>players.every(restored),'the final result reaches every player')
  await pause(450)
  for (const state of players) {
    assert.ok(state.messages.includes(result),result)
    const index = state.messages.lastIndexOf('Final standings:')
    assert.deepEqual(state.messages.slice(index+1,index+1+standings.length),standings)
    const rewards = state.messages.filter(line=>line.startsWith('Round reward: +'))
    assert.equal(rewards.length,state.aces>0 ? 1 : 0,'only aces pay a round reward')
    if (state.aces>0) assert.ok(rewards[0].startsWith('Round reward: +'+state.aces*10+' credits.'))
    assert.equal(state.bot.game.gameMode,state.original.mode,'game mode restored')
    assert.ok(state.bot.entity.position.distanceTo(state.original.position)<2,'lobby location restored')
    assert.deepEqual(inventory(state.bot),state.original.items,'inventory restored')
    await command(state,'status',/^You are not in a round or queue\.$/)
  }
}

async function run(name, count, play) {
  const players = Array.from({length:count},(_,i)=>Object.assign(connect('Ace'+name+'ABC'[i]+process.pid%10000),{aces:0}))
  try { await play(players) }
  finally {
    for (const {bot} of players) bot.quit()
    await pause(700)
  }
}

async function main() {
  await run('Tie',3,async players=>{
    const [a,b,c] = players
    await start(players,true)
    await playHole(players,1,['ace','miss','miss'])
    await playHole(players,2,['miss','ace','miss'])
    await command(c,'score',new RegExp('^1\\. '+b.name+' - 1 ace$'))
    await playHole(players,3,['ace','ace','miss'])
    await finish(players,'Ace Race result: '+a.name+', '+b.name+' tie for first with 2 aces each.',
      ['1. '+a.name+' - 2 aces','1. '+b.name+' - 2 aces','3. '+c.name+' - 0 aces'])
    console.log('PASS: three players finish a full Ace Race, share first place and receive exact ace credits')
  })
  await run('Win',2,async players=>{
    const [a,b] = players
    await start(players,false)
    await playHole(players,1,['ace','pass'])
    await playHole(players,2,['ace','timeout'])
    await playHole(players,3,['miss','miss'])
    await finish(players,'Ace Race result: '+a.name+' wins with 2 aces.',
      ['1. '+a.name+' - 2 aces','2. '+b.name+' - 0 aces'])
    console.log('PASS: separate queue entries get a clear winner, and passes and timeouts use up the attempt')
  })
}

main().catch(error=>{console.error(error);process.exitCode=1}).finally(()=>process.exit(process.exitCode||0))
